"""
Tool Registry — self-describing, constrained, auditable tools.

Key concepts from the talk:
 1. Tools = typed Python functions with docstrings (one source of truth)
 2. Partial Function Application (PFA) — pre-bind args the LLM can't see
 3. Dangerous flag — marks tools that need human approval
 4. Categories — organize tools by domain
"""

from __future__ import annotations

import inspect
import functools
import textwrap
import json
from dataclasses import dataclass, field
from typing import Any, Callable


@dataclass
class Tool:
    """A self-describing tool the agent can use."""

    name: str
    description: str
    parameters: dict   # JSON Schema for LLM
    fn: Callable       # the actual Python function
    dangerous: bool = False
    category: str = "general"
    constrained_args: dict = field(default_factory=dict)
    # Metadata for tracing and debugging
    source_file: str = ""
    source_line: int = 0

    def to_api_schema(self) -> dict:
        """Convert to Anthropic/OpenAI tool format."""
        return {
            "name": self.name,
            "description": self.description,
            "input_schema": self.parameters,
        }

    def execute(self, **kwargs) -> str:
        """Execute the tool and return string result."""
        try:
            result = self.fn(**kwargs)
            return str(result)
        except Exception as e:
            return f"ToolError({self.name}): {e}"


class ToolRegistry:
    """
    Collects and manages tools.

    Each tool is a Python function with a docstring and type hints.
    Those become the tool's description and JSON Schema that the LLM reads.

    KEY FEATURES:
    - PFA: `constrain` pre-binds arguments the LLM can't see or override
    - Dangerous marking: tools that need human approval
    - Self-documenting: docstring = LLM description, type hints = schema
    """

    def __init__(self):
        self._tools: dict[str, Tool] = {}

    # ── Registration ──

    def register(
        self,
        dangerous: bool = False,
        category: str = "general",
        constrain: dict | None = None,
        description: str | None = None,
    ) -> Callable:
        """
        Decorator: turn a Python function into a registered tool.

        Args:
            dangerous: If True, human must approve before execution.
            category: Group name for organizing tools (e.g. 'filesystem', 'web').
            constrain: Dict of pre-bound arguments (PFA). These are NEVER
                       shown to the LLM and CANNOT be overridden.
            description: Override the docstring-based description.

        Example:
            @tools.register(
                dangerous=True,
                category="filesystem",
                constrain={"base_dir": "/tmp/safe"}
            )
            def write_file(filename: str, content: str, base_dir: str = "/tmp"):
                ...

            The LLM sees only `filename` and `content`.
            `base_dir` is silently pre-bound to `/tmp/safe` — deterministic safety.
        """
        def decorator(fn: Callable) -> Callable:
            # Build JSON Schema from type hints
            sig = inspect.signature(fn)
            properties = {}
            required = []
            constrained_args = dict(constrain or {})

            for param_name, param in sig.parameters.items():
                if param_name in constrained_args:
                    continue  # PFA: hidden from LLM

                param_type = self._type_to_json(param.annotation)

                # Extract parameter description from docstring
                param_desc = f"Parameter: {param_name}"
                if param.default is not inspect.Parameter.empty:
                    param_desc += f" (default: {param.default})"

                properties[param_name] = {
                    "type": param_type,
                    "description": param_desc,
                }

                if param.default is inspect.Parameter.empty:
                    required.append(param_name)

            # Build function that applies constrained args
            wrapped_fn = fn
            if constrain:
                @functools.wraps(fn)
                def wrapped_fn(*args, **kwargs):
                    return fn(*args, **{**constrain, **kwargs})

            # Extract source info for debugging
            try:
                source_file = inspect.getfile(fn)
                _, source_line = inspect.getsourcelines(fn)
            except (TypeError, OSError):
                source_file = ""
                source_line = 0

            tool = Tool(
                name=fn.__name__,
                description=description or textwrap.dedent(fn.__doc__ or "").strip(),
                parameters={
                    "type": "object",
                    "properties": properties,
                    "required": required,
                },
                fn=wrapped_fn,
                dangerous=dangerous,
                category=category,
                constrained_args=constrained_args,
                source_file=source_file,
                source_line=source_line,
            )
            self._tools[fn.__name__] = tool
            return wrapped_fn

        return decorator

    def add_function(
        self,
        fn: Callable,
        dangerous: bool = False,
        category: str = "general",
        constrain: dict | None = None,
        description: str | None = None,
    ) -> Tool:
        """Register a function as a tool programmatically (non-decorator)."""
        self.register(dangerous=dangerous, category=category,
                      constrain=constrain, description=description)(fn)
        return self._tools[fn.__name__]

    # ── Access ──

    def get(self, name: str) -> Tool | None:
        return self._tools.get(name)

    def get_all(self) -> list[Tool]:
        return list(self._tools.values())

    def get_by_category(self, category: str) -> list[Tool]:
        return [t for t in self._tools.values() if t.category == category]

    def list_tools(self) -> str:
        """Human-readable tool listing for debugging."""
        lines = []
        for t in self._tools.values():
            danger = "⚠️  DANGEROUS" if t.dangerous else "✓ safe"
            constrained = f" [constrained: {list(t.constrained_args)}]" if t.constrained_args else ""
            lines.append(f"  {t.name} ({t.category}) — {danger}{constrained}")
            lines.append(f"    {t.description[:100]}")
        return "\n".join(lines)

    def to_api_format(self) -> list[dict]:
        """Convert all tools to API-compatible format."""
        return [t.to_api_schema() for t in self._tools.values()]

    def __len__(self) -> int:
        return len(self._tools)

    def __contains__(self, name: str) -> bool:
        return name in self._tools

    @staticmethod
    def _type_to_json(annotation) -> str:
        """Map Python type to JSON Schema type."""
        if annotation is inspect.Parameter.empty:
            return "string"
        type_map = {
            str: "string", int: "integer", float: "number",
            bool: "boolean", list: "array", dict: "object",
        }
        origin = getattr(annotation, "__origin__", None)
        if origin is list:
            return "array"
        return type_map.get(annotation, "string")

"""
Guardrails — deterministic safety that doesn't depend on model behavior.

From the talk: "prompts are not security."
Guardrails enforce rules REGARDLESS of what the model asks for.

Types of guardrails:
 1. InputGuardrail — validate/filter what goes INTO the model
 2. OutputGuardrail — validate/filter what comes OUT of the model
 3. ContentFilter — block sensitive content
 4. RateLimiter — prevent abuse
 5. ToolAllowlist — restrict which tools are available
 6. GuardrailPipeline — compose multiple guardrails
"""

from __future__ import annotations

import re
import time
import json
from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import Any, Callable


@dataclass
class GuardrailResult:
    """Result of a guardrail check."""
    allowed: bool = True
    reason: str = ""
    modified_content: str | None = None  # if the guardrail rewrote the content
    metadata: dict = field(default_factory=dict)


class Guardrail(ABC):
    """Base class for all guardrails."""

    name: str = "base"

    @abstractmethod
    def check(self, content: str, context: dict | None = None) -> GuardrailResult:
        """Check content against this guardrail."""
        ...


# ═══════════════════════════════════════════════════════════════════════
# Input Guardrails — filter what goes into the model
# ═══════════════════════════════════════════════════════════════════════

class InputGuardrail(Guardrail):
    """Guardrail applied to user input before it reaches the model."""


class PIIFilter(InputGuardrail):
    """
    Detect and redact personally identifiable information from prompts.
    Email, phone numbers, credit cards, SSNs — stripped before the LLM sees them.
    """

    name = "pii_filter"

    PATTERNS = {
        "email": r"\b[\w\.-]+@[\w\.-]+\.\w+\b",
        "phone": r"\b\d{3}[-.]?\d{3}[-.]?\d{4}\b",
        "credit_card": r"\b\d{4}[-\s]?\d{4}[-\s]?\d{4}[-\s]?\d{4}\b",
        "ssn": r"\b\d{3}-\d{2}-\d{4}\b",
    }

    def __init__(self, redact: list[str] | None = None):
        self.redact_fields = redact or list(self.PATTERNS.keys())

    def check(self, content: str, context: dict | None = None) -> GuardrailResult:
        modified = content
        found = []
        for field in self.redact_fields:
            pattern = self.PATTERNS.get(field)
            if pattern:
                matches = re.findall(pattern, content)
                if matches:
                    found.extend(matches)
                    modified = re.sub(pattern, f"[REDACTED_{field.upper()}]", modified)

        if found:
            return GuardrailResult(
                allowed=True,  # still allow, just redacted
                reason=f"Redacted {len(found)} PII instances: {', '.join(self.redact_fields)}",
                modified_content=modified,
                metadata={"redacted_count": len(found), "types": list(set(self.redact_fields))},
            )
        return GuardrailResult(allowed=True)


class KeywordBlocklist(InputGuardrail):
    """
    Block prompts containing forbidden keywords.
    Useful for preventing prompt injection, abuse, or off-topic requests.
    """

    name = "keyword_blocklist"

    def __init__(self, keywords: list[str] | None = None):
        self.keywords = keywords or [
            "ignore all previous instructions",
            "disregard your system prompt",
            "you are now DAN",
            "pretend you are",
        ]

    def check(self, content: str, context: dict | None = None) -> GuardrailResult:
        content_lower = content.lower()
        for kw in self.keywords:
            if kw.lower() in content_lower:
                return GuardrailResult(
                    allowed=False,
                    reason=f"Blocked by keyword: '{kw}'",
                    metadata={"matched_keyword": kw},
                )
        return GuardrailResult(allowed=True)


class MaxLengthGuardrail(InputGuardrail):
    """Reject prompts that exceed a maximum length."""

    name = "max_length"

    def __init__(self, max_chars: int = 32000):
        self.max_chars = max_chars

    def check(self, content: str, context: dict | None = None) -> GuardrailResult:
        if len(content) > self.max_chars:
            return GuardrailResult(
                allowed=False,
                reason=f"Input too long ({len(content)} chars, max {self.max_chars})",
            )
        return GuardrailResult(allowed=True)


# ═══════════════════════════════════════════════════════════════════════
# Output Guardrails — filter what comes out of the model
# ═══════════════════════════════════════════════════════════════════════

class OutputGuardrail(Guardrail):
    """Guardrail applied to model output before it reaches the user."""


class ContentFilter(OutputGuardrail):
    """
    Block model outputs containing specific patterns.
    Default: block API keys, secrets, and sensitive patterns.
    """

    name = "content_filter"

    SECRET_PATTERNS = [
        (r"sk-[a-zA-Z0-9]{32,}", "OpenAI API key"),
        (r"sk-ant-[a-zA-Z0-9_-]{32,}", "Anthropic API key"),
        (r"AIza[0-9A-Za-z\-_]{35}", "Google API key"),
        (r"ghp_[a-zA-Z0-9]{36}", "GitHub personal access token"),
        (r"-----BEGIN (?:RSA |EC |DSA )?PRIVATE KEY-----", "Private key"),
    ]

    def __init__(self, extra_patterns: list[tuple[str, str]] | None = None):
        self.patterns = self.SECRET_PATTERNS + (extra_patterns or [])

    def check(self, content: str, context: dict | None = None) -> GuardrailResult:
        for pattern, label in self.patterns:
            if re.search(pattern, content):
                return GuardrailResult(
                    allowed=False,
                    reason=f"Output blocked: contains {label}",
                    metadata={"pattern": label},
                )
        return GuardrailResult(allowed=True)


# ═══════════════════════════════════════════════════════════════════════
# Operational Guardrails
# ═══════════════════════════════════════════════════════════════════════

class RateLimiter(Guardrail):
    """
    Rate limit tool executions to prevent abuse.
    Tracks calls per time window.
    """

    name = "rate_limiter"

    def __init__(self, max_calls: int = 100, window_seconds: float = 60.0):
        self.max_calls = max_calls
        self.window = window_seconds
        self._calls: list[float] = []

    def check(self, content: str = "", context: dict | None = None) -> GuardrailResult:
        now = time.time()
        # Purge old entries
        self._calls = [t for t in self._calls if now - t < self.window]
        self._calls.append(now)

        if len(self._calls) > self.max_calls:
            return GuardrailResult(
                allowed=False,
                reason=f"Rate limit exceeded: {len(self._calls)} calls in {self.window}s (max {self.max_calls})",
                metadata={"current_rate": len(self._calls), "limit": self.max_calls},
            )
        return GuardrailResult(allowed=True)


class ToolAllowlist(Guardrail):
    """
    Restrict which tools are available to an agent.
    Applied at the harness level — the model never sees blocked tools.

    This is PFA at the harness level: even if the model generates
    a tool call, it won't find it in the registry.
    """

    name = "tool_allowlist"

    def __init__(self, allowed_tools: list[str]):
        self.allowed = set(allowed_tools)

    def check(self, tool_name: str, context: dict | None = None) -> GuardrailResult:
        if tool_name not in self.allowed:
            return GuardrailResult(
                allowed=False,
                reason=f"Tool '{tool_name}' not in allowlist: {sorted(self.allowed)}",
            )
        return GuardrailResult(allowed=True)

    def filter_tools(self, tools: list[dict]) -> list[dict]:
        """Remove disallowed tools from the API schema."""
        return [t for t in tools if t["name"] in self.allowed]


# ═══════════════════════════════════════════════════════════════════════
# Pipeline — compose multiple guardrails
# ═══════════════════════════════════════════════════════════════════════

class GuardrailPipeline:
    """
    Chain multiple guardrails together.
    Applies input guardrails → model → output guardrails.
    Stops at the first rejection (fail-fast).
    """

    def __init__(self):
        self.input_guardrails: list[InputGuardrail] = []
        self.output_guardrails: list[OutputGuardrail] = []
        self.operational_guardrails: list[Guardrail] = []

    def add_input(self, guardrail: InputGuardrail) -> "GuardrailPipeline":
        self.input_guardrails.append(guardrail)
        return self

    def add_output(self, guardrail: OutputGuardrail) -> "GuardrailPipeline":
        self.output_guardrails.append(guardrail)
        return self

    def add_operational(self, guardrail: Guardrail) -> "GuardrailPipeline":
        self.operational_guardrails.append(guardrail)
        return self

    def check_input(self, content: str, context: dict | None = None) -> GuardrailResult:
        """Run all input guardrails. Returns first rejection or last result."""
        modified = content
        for gr in self.input_guardrails:
            result = gr.check(modified, context)
            if not result.allowed:
                return result
            if result.modified_content is not None:
                modified = result.modified_content
        return GuardrailResult(allowed=True, modified_content=modified)

    def check_output(self, content: str, context: dict | None = None) -> GuardrailResult:
        """Run all output guardrails. Returns first rejection."""
        for gr in self.output_guardrails:
            result = gr.check(content, context)
            if not result.allowed:
                return result
        return GuardrailResult(allowed=True)

    def check_operational(self, tool_name: str = "", context: dict | None = None) -> GuardrailResult:
        """Run operational guardrails (rate limit, tool allowlist)."""
        for gr in self.operational_guardrails:
            if isinstance(gr, ToolAllowlist):
                result = gr.check(tool_name, context)
            else:
                result = gr.check("", context)
            if not result.allowed:
                return result
        return GuardrailResult(allowed=True)

    @classmethod
    def default(cls) -> "GuardrailPipeline":
        """Create a pipeline with sensible defaults."""
        return (
            cls()
            .add_input(KeywordBlocklist())
            .add_input(MaxLengthGuardrail())
            .add_input(PIIFilter(redact=["email", "credit_card"]))
            .add_output(ContentFilter())
            .add_operational(RateLimiter(max_calls=100, window_seconds=60))
        )

"""
Tracing — execution observability for debugging agent loops.

From the talk: you need to see what happened, step by step.
Trace every model call, tool execution, and guardrail decision.
"""

from __future__ import annotations

import time
import json
from dataclasses import dataclass, field
from enum import Enum
from typing import Any


class TraceLevel(str, Enum):
    """How much detail to trace."""
    OFF = "off"
    STEPS = "steps"          # one line per step
    DETAILED = "detailed"    # tool inputs and outputs
    FULL = "full"            # raw API messages


@dataclass
class TraceEvent:
    """A single event in the execution trace."""
    step: int
    timestamp: float
    event_type: str  # "reason", "act", "observe", "guardrail", "error", "complete"
    data: dict = field(default_factory=dict)

    @property
    def elapsed_ms(self) -> int:
        return int(self.data.get("elapsed_ms", 0))

    def summary(self) -> str:
        """One-line summary for quick scanning."""
        et = self.event_type
        if et == "reason":
            return f"  [{self.step:02d}] REASON → {self.data.get('tool', 'thinking')}"
        elif et == "act":
            return f"  [{self.step:02d}] ACT    → {self.data.get('tool', '?')}({self._short_input()})"
        elif et == "observe":
            result = self.data.get("result", "")
            short = result[:80].replace("\n", " ")
            return f"  [{self.step:02d}] OBSERVE← {short}"
        elif et == "guardrail":
            return f"  [{self.step:02d}] GUARD  → {self.data.get('reason', 'blocked')}"
        elif et == "error":
            return f"  [{self.step:02d}] ERROR  → {self.data.get('error', 'unknown')}"
        elif et == "complete":
            return f"  [{self.step:02d}] DONE   → {self.data.get('stop_reason', 'end')}"
        return f"  [{self.step:02d}] {et}: {self.data}"

    def _short_input(self) -> str:
        inp = self.data.get("input", {})
        if not inp:
            return ""
        items = [f"{k}={json.dumps(v)[:40]}" for k, v in inp.items()]
        return ", ".join(items)[:100]


@dataclass
class Tracer:
    """
    Records every step of the agent's execution loop.

    Usage:
        tracer = Tracer(level=TraceLevel.DETAILED)
        harness = Harness(tools=tools, tracer=tracer)
        harness.run_task("Do something")
        tracer.print_trace()
    """

    level: TraceLevel = TraceLevel.STEPS
    events: list[TraceEvent] = field(default_factory=list)
    start_time: float = 0.0

    def __post_init__(self):
        self.start_time = time.time()

    def record(self, step: int, event_type: str, **data) -> TraceEvent:
        """Record an event in the trace."""
        now = time.time()
        data["elapsed_ms"] = int((now - self.start_time) * 1000)
        event = TraceEvent(
            step=step,
            timestamp=now,
            event_type=event_type,
            data=data,
        )
        self.events.append(event)
        return event

    # ── Convenience methods ──

    def reason(self, step: int, text: str, tool: str = "") -> TraceEvent:
        if self.level == TraceLevel.OFF:
            return None
        return self.record(step, "reason", text=text[:200], tool=tool)

    def act(self, step: int, tool_name: str, tool_input: dict) -> TraceEvent:
        if self.level == TraceLevel.OFF:
            return None
        if self.level == TraceLevel.STEPS:
            return self.record(step, "act", tool=tool_name, input_summary=str(list(tool_input.keys())))
        return self.record(step, "act", tool=tool_name, input=tool_input)

    def observe(self, step: int, result: str) -> TraceEvent:
        if self.level == TraceLevel.OFF:
            return None
        return self.record(step, "observe", result=result[:500])

    def guardrail_block(self, step: int, reason: str, guardrail_name: str = "") -> TraceEvent:
        if self.level == TraceLevel.OFF:
            return None
        return self.record(step, "guardrail", reason=reason, name=guardrail_name, blocked=True)

    def error(self, step: int, error_msg: str, tool_name: str = "") -> TraceEvent:
        if self.level == TraceLevel.OFF:
            return None
        return self.record(step, "error", error=error_msg, tool=tool_name)

    def complete(self, step: int, stop_reason: str, answer_preview: str = "") -> TraceEvent:
        if self.level == TraceLevel.OFF:
            return None
        return self.record(step, "complete", stop_reason=stop_reason, preview=answer_preview[:200])

    # ── Output ──

    def print_trace(self) -> None:
        """Print a readable trace of the entire run."""
        if not self.events:
            print("  (no trace events)")
            return

        total_ms = self.events[-1].data.get("elapsed_ms", 0)
        print(f"\n  Trace ({len(self.events)} events, {total_ms}ms total)")
        print("  " + "─" * 58)
        for evt in self.events:
            print(evt.summary())

    def to_json(self) -> str:
        """Export trace as JSON for logging or analysis."""
        return json.dumps(
            [{"step": e.step, "type": e.event_type, "ms": e.data.get("elapsed_ms", 0), **e.data}
             for e in self.events],
            indent=2,
            default=str,
        )

    def clear(self) -> None:
        """Reset the trace."""
        self.events.clear()
        self.start_time = time.time()

    def add_input(self, guardrail: InputGuardrail) -> "GuardrailPipeline":
        self.input_guardrails.append(guardrail)
        return self

    def add_output(self, guardrail: OutputGuardrail) -> "GuardrailPipeline":
        self.output_guardrails.append(guardrail)
        return self

    def add_operational(self, guardrail: Guardrail) -> "GuardrailPipeline":
        self.operational_guardrails.append(guardrail)
        return self

    def check_input(self, content: str, context: dict | None = None) -> GuardrailResult:
        """Run all input guardrails. Returns first rejection or last result."""
